import fs from 'node:fs';import path from 'node:path';import {fileURLToPath} from 'node:url';import crypto from 'node:crypto';import {createRequire} from 'node:module';
import {createEVM} from '@ethereumjs/evm';import {Common,Mainnet,Hardfork} from '@ethereumjs/common';import {Account,createAddressFromString,hexToBytes,bytesToHex} from '@ethereumjs/util';
const here=path.dirname(fileURLToPath(import.meta.url));const require=createRequire(process.env.KEEL_SDK_PATH ? process.env.KEEL_SDK_PATH+'/package.json' : import.meta.url),solc=require('solc'),viem=require('viem');const sdk=process.env.KEEL_SDK_PATH??here;
const records={...JSON.parse(fs.readFileSync(path.join(here,'sources.json'))),...JSON.parse(fs.readFileSync(path.join(here,'more-sources.json')))};const sources=Object.fromEntries(Object.entries(records).map(([p,v])=>[p,{content:v.content}]));
const graphSize=628198, graph=Buffer.alloc(graphSize,97), digest='0x'+crypto.createHash('sha256').update(graph).digest('hex'),objectId='0x'+'11'.repeat(32);const chunk=24000,count=Math.ceil(graphSize/chunk),hold='0x'+'22'.repeat(20),builder='0x'+'33'.repeat(20),caller='0x'+'44'.repeat(20);
sources['SyntheticHold.sol']={content:`pragma solidity 0.8.36; import {IKeelHold} from "src/modules/keel-hold/interfaces/IKeelHold.sol"; contract SyntheticHold { function getObject(bytes32) external pure returns(IKeelHold.ObjectRecord memory r) {r.digest=${digest};r.byteLength=${graphSize};r.storedByteLength=${graphSize};r.slugCount=${count};r.exists=true;r.mediaType="application/vnd.keel.token-uri-raw-percent-fragment";} function getObjectSlugPointers(bytes32,uint256,uint256) external pure returns(address[] memory p){p=new address[](${count});for(uint i;i<${count};i++)p[i]=address(uint160(0x1000+i));}}`};
const input={language:'Solidity',sources,settings:{optimizer:{enabled:true,runs:50},viaIR:true,evmVersion:'prague',metadata:{bytecodeHash:'none',appendCBOR:false},outputSelection:{'*':{'*':['abi','evm.deployedBytecode.object','evm.deployedBytecode.immutableReferences']}}}};
const cache=path.join(here,'compiled.json');let output;if(fs.existsSync(cache))output=JSON.parse(fs.readFileSync(cache));else{console.log('Compiling pinned builder',solc.version());output=JSON.parse(solc.compile(JSON.stringify(input),{import:p=>{let resolved=p.startsWith('@keel/')?'src/modules/'+p.slice(6):p;if(sources[resolved])return {contents:sources[resolved].content};const local=sdk+'/node_modules/'+p;if(fs.existsSync(local))return {contents:fs.readFileSync(local,'utf8')};return {error:'Missing '+p+' => '+resolved};}}));const errors=output.errors?.filter(e=>e.severity==='error');if(errors?.length){console.log(errors);process.exit(1)}fs.writeFileSync(cache,JSON.stringify(output));}
const name='src/modules/keel-harness/KeelRawTokenURIBuilder.sol';const artifact=output.contracts[name].KeelRawTokenURIBuilder;let code=artifact.evm.deployedBytecode.object;for(const refs of Object.values(artifact.evm.deployedBytecode.immutableReferences))for(const ref of refs)code=code.slice(0,ref.start*2)+hold.slice(2).padStart(ref.length*2,'0')+code.slice((ref.start+ref.length)*2);
const evm=await createEVM({common:new Common({chain:Mainnet,hardfork:Hardfork.Prague})});await evm.stateManager.putCode(createAddressFromString(hold),hexToBytes('0x'+output.contracts['SyntheticHold.sol'].SyntheticHold.evm.deployedBytecode.object));await evm.stateManager.putCode(createAddressFromString(builder),hexToBytes('0x'+code));await evm.stateManager.putAccount(createAddressFromString(caller),new Account(0n,10n**30n));for(let i=0;i<count;i++)await evm.stateManager.putCode(createAddressFromString('0x'+(0x1000+i).toString(16).padStart(40,'0')),new Uint8Array(Buffer.concat([Buffer.from([0]),graph.subarray(i*chunk,(i+1)*chunk)])));
const literalMask=0x0000000000000000000000000000000047fffffe87ffffff2fffff1200000000n;const escape=s=>Array.from(Buffer.from(s),b=>b<128&&((literalMask>>BigInt(b))&1n)?String.fromCharCode(b):'%'+b.toString(16).toUpperCase().padStart(2,'0')).join('');
function envelope(previewSize,pattern='base64'){const svgHead='<svg xmlns="http://www.w3.org/2000/svg">',svgTail='</svg>';const payload=pattern==='escaped'?'data:image/svg+xml,'+escape(svgHead+' '.repeat(Math.max(0,previewSize-svgHead.length-svgTail.length))+svgTail):'data:image/webp;base64,'+Buffer.alloc(previewSize,0).toString('base64');const rawPrefix=`{"name":"Synthetic","description":"Synthetic data only","image":"${payload}","animation_url":"data:text/html;charset=utf-8,`;const rawSuffix='%3Cscript%3E0%3C%2Fscript%3E","keel_schema":"keel-manifest@2"}';return {rawPrefix,rawSuffix,encodedPrefix:escape(rawPrefix),encodedSuffix:escape(rawSuffix)};}
async function call(method,e,gasLimit=200_000_000n){const prepared=method==='preparedTokenURI';const prefix=Buffer.from(prepared?e.encodedPrefix:e.rawPrefix),suffix=Buffer.from(prepared?e.encodedSuffix:e.rawSuffix);const data=viem.encodeFunctionData({abi:artifact.abi,functionName:method,args:[objectId,digest,'0x'+prefix.toString('hex'),'0x'+suffix.toString('hex')]});evm.journal.cleanJournal();evm.journal.addAlwaysWarmAddress(caller.slice(2));evm.journal.addAlwaysWarmAddress(builder.slice(2));for(let p=1;p<=17;p++)evm.journal.addAlwaysWarmAddress(p.toString(16).padStart(40,'0'));const t=Date.now();const intrinsicBudget=21000+hexToBytes(data).reduce((n,b)=>n+(b?16:4),0);const result=await evm.runCall({caller:createAddressFromString(caller),to:createAddressFromString(builder),data:hexToBytes(data),gasLimit:gasLimit-BigInt(intrinsicBudget),isStatic:true});const r=result.execResult;const decoded=r.exceptionError?undefined:viem.decodeAbiParameters([{type:'string'}],bytesToHex(r.returnValue))[0]; const expected='data:application/json;charset=utf-8,'+e.encodedPrefix+graph.toString()+e.encodedSuffix; if(decoded!==undefined&&decoded!==expected)throw Error('Exact output mismatch '+method);const calldata=hexToBytes(data),nonzero=calldata.reduce((n,b)=>n+(b!==0),0),intrinsic=21000+nonzero*16+(calldata.length-nonzero)*4;return {method,gasLimit:gasLimit.toString(),executionGas:r.executionGasUsed.toString(),intrinsicGas:intrinsic,totalGas:(r.executionGasUsed+BigInt(intrinsic)).toString(),calldataBytes:calldata.length,prefixBytes:prefix.length,suffixBytes:suffix.length,error:r.exceptionError?.error??null,exactOutputMatch:decoded===expected,returnBytes:r.returnValue.length,returnSha256:crypto.createHash('sha256').update(r.returnValue).digest('hex'),ms:Date.now()-t};}
const results=[];for(const n of [0,18506,50000,100000]){const e=envelope(n);for(const m of ['preparedTokenURI','preEncodedTokenURI']){const r=await call(m,e);r.previewDecodedBytes=n;r.pattern='base64';results.push(r);console.log(JSON.stringify(r));fs.writeFileSync(path.join(here,'rerun-results.json'),JSON.stringify({graphBytes:graphSize,sourceCommit:'ace3fed7aff1765c7d2ee9bba4d0232246f86ffb',compiler:solc.version(),compilerSettings:input.settings,results},null,2));}}
const e=envelope(18506,'escaped');for(const m of ['preparedTokenURI','preEncodedTokenURI']){const r=await call(m,e);r.previewDecodedBytes=18506;r.pattern='escaped';results.push(r);console.log(JSON.stringify(r));}
for(const n of [18506]){const r=await call('preparedTokenURI',envelope(n,'escaped'),60_000_000n);r.previewDecodedBytes=n;r.pattern='escaped-cap';results.push(r);console.log(JSON.stringify(r));}
fs.writeFileSync(path.join(here,'rerun-results.json'),JSON.stringify({graphBytes:graphSize,sourceCommit:'ace3fed7aff1765c7d2ee9bba4d0232246f86ffb',compiler:solc.version(),compilerSettings:input.settings,results},null,2));
